import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import '../../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../data/Sources/product_details_sources.dart';import '../../data/entities/product_details.dart';import '../../data/repositories/product_details_repo.dart';class ProductDetailsRepoImpl extends ProductDetailsRepo {  @override  Future<Either<Failure, ProductDetailsEntities>> getProductDetails(      {required int id}) async {    try {      final response = await ProductDetailsSources.getProductDetails(        id: id,      );      print("response:: ${response.primaryImage?.imageUrl}");      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }}